import{_ as l,a0 as r,w as o,s as p,ao as d,I as n,x as s,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Git 中上下文切換的 4 種方式 | LCTT x X-CMD","titleTemplate":false,"description":"Git 中上下文切換的 4 種方式 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 中上下文切換的 4 種方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 中上下文切換的 4 種方式 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210414 4 tips for context switching in Git","title":"Git 中上下文切換的 4 種方式","tag":"202105","desc":""},"relativePath":"202105/20210414 4 tips for context switching in Git.md","filePath":"[post].md"}'),c={name:"202105/20210414 4 tips for context switching in Git.md"};function h(g,e,u,k,f,b){const t=r("Link");return o(),p("div",null,[e[15]||(e[15]=d(`<h1 id="git-中上下文切換的-4-種方式" tabindex="-1">Git 中上下文切換的 4 種方式 <a class="header-anchor" href="#git-中上下文切換的-4-種方式" aria-label="Permalink to “Git 中上下文切換的 4 種方式”">​</a></h1><blockquote><p>比較 Git 中四種切換分支的方法的優缺點。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/25/091803a6ww3r7yo32oxdzx.jpg" alt=""></p><p>所有大量使用 Git 的人都會用到某種形式的上下文切換。有時這隻會給你的工作流程增加少量的開銷，但有時，這可能是一段痛苦的經歷。</p><p>讓我們用以下這個例子來討論一些常見的上下文切換策略的優缺點：</p><blockquote><p>假設你在一個名為 <code>feature-X</code> 的分支中工作。你剛剛發現你需要解決一個無關的問題。這不能在 <code>feature-X</code> 分支中完成。你需要在一個新的分支 <code>feature-Y</code> 中完成這項工作。</p></blockquote><h3 id="方案-1-暫存-分支" tabindex="-1">方案 1：暫存 + 分支 <a class="header-anchor" href="#方案-1-暫存-分支" aria-label="Permalink to “方案 1：暫存 + 分支”">​</a></h3><p>解決此問題最常見的工作流程可能如下所示：</p><ol><li>停止分支 <code>feature-X</code> 上的工作</li><li><code>git stash</code></li><li><code>git checkout -b feature-Y origin/main</code></li><li>一頓鼓搗，解決 <code>feature-Y</code> 的問題</li><li><code>git checkout feature-X</code> 或 <code>git switch -</code></li><li><code>git stash pop</code></li><li>繼續在 <code>feature-X</code> 中工作</li></ol><p><strong>優點：</strong> 這種方法的優點在於，對於簡單的更改，這是一個相當簡單的工作流程。它可以很好地工作，特別是對於小型倉庫。</p><p><strong>缺點：</strong> 使用此工作流程時，一次只能有一個工作區。另外，根據你的倉庫的狀態，使用暫存是一個麻煩的環節。</p><h3 id="方案-2-wip-提交-分支" tabindex="-1">方案 2：WIP 提交 + 分支 <a class="header-anchor" href="#方案-2-wip-提交-分支" aria-label="Permalink to “方案 2：WIP 提交 + 分支”">​</a></h3><p>這個解決方案和前一個非常相似，但是它使用 WIP（<ruby>正在進行的工作<rt>Work in Progress</rt></ruby>）提交而不是暫存。當你準備好切換回來，而不是彈出暫存時，<code>git reset HEAD~1</code> 會展開 WIP 提交，你可以自由地繼續，就像之前的方案一樣，但不會觸及暫存。</p><ol><li>停止分支 <code>feature-X</code> 上的工作</li><li><code>git add -u</code>（僅僅添加修改和刪除的文件）</li><li><code>git commit -m &quot;WIP&quot;</code></li><li><code>git checkout -b feature-Y origin/master</code></li><li>一頓鼓搗，解決 <code>feature-Y</code> 的問題</li><li><code>git checkout feature-X</code> 或 <code>git switch -</code></li><li><code>git reset HEAD~1</code></li></ol><p><strong>優點：</strong> 對於簡單的更改，這是一個簡單的工作流，也適合於小型倉庫。你不需要使用暫存。</p><p><strong>缺點：</strong> 任何時候都只能有一個工作區。此外，如果你或你的代碼審閲者不夠謹慎，WIP 提交可能會合併到最終產品。</p><p>使用此工作流時，你<strong>永遠</strong>不要想着將 <code>--hard</code> 添加到 <code>git reset</code>。如果你不小心這樣做了，你應該能夠使用 <code>git reflog</code> 恢復提交，但是你最好完全避免這種情況發生，否則你會聽到心碎的聲音。</p><h3 id="方案-3-克隆一個新倉庫" tabindex="-1">方案 3：克隆一個新倉庫 <a class="header-anchor" href="#方案-3-克隆一個新倉庫" aria-label="Permalink to “方案 3：克隆一個新倉庫”">​</a></h3><p>在這個解決方案中，不是創建新的分支，而是為每個新的功能分支創建存儲庫的新克隆。</p><p><strong>優點：</strong> 你可以同時在多個工作區中工作。你不需要 <code>git stash</code> 或者是 WIP 提交。</p><p><strong>缺點：</strong> 需要考慮倉庫的大小，因為這可能會佔用大量磁盤空間（淺層克隆可以幫助解決這種情況，但它們可能並不總是很合適。）此外，你的倉庫克隆將互不可知。因為他們不能互相追蹤，所以你必須手動追蹤你的克隆的源倉庫。如果需要 git 鈎子，則需要為每個新克隆設置它們。</p><h3 id="方案-4-git-工作樹" tabindex="-1">方案 4：git 工作樹 <a class="header-anchor" href="#方案-4-git-工作樹" aria-label="Permalink to “方案 4：git 工作樹”">​</a></h3><p>要使用此解決方案，你可能需要了解 <code>git add worktree</code>。如果你不熟悉 Git 中的工作樹，請不要難過。許多人多年來都對這個概念一無所知。</p><h4 id="什麼是工作樹" tabindex="-1">什麼是工作樹？ <a class="header-anchor" href="#什麼是工作樹" aria-label="Permalink to “什麼是工作樹？”">​</a></h4><p>將工作樹視為倉庫中屬於項目的文件。本質上，這是一種工作區。你可能沒有意識到你已經在使用工作樹了。開始使用 Git 時，你將自動獲得第一個工作樹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /tmp/foo &amp;&amp; cd /tmp/foo</span></span>
<span class="line"><span>$ git init</span></span>
<span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/tmp  0000000 [master]</span></span></code></pre></div><p>你可以在以上代碼看到，甚至在第一次提交前你就有了一個工作樹。接下來去嘗試再添加一個工作樹到你的項目中吧。</p><h4 id="添加一個工作樹" tabindex="-1">添加一個工作樹 <a class="header-anchor" href="#添加一個工作樹" aria-label="Permalink to “添加一個工作樹”">​</a></h4><p>想要添加一個新的工作樹你需要提供:</p><ol><li>硬盤上的一個位置</li><li>一個分支名</li><li>添加哪些分支</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/oalders/http-browserdetect.git</span></span>
<span class="line"><span>$ cd http-browserdetect/</span></span>
<span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/Users/olaf/http-browserdetect  90772ae [master]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git worktree add ~/trees/oalders/feature-X -b oalders/feature-X origin/master</span></span>
<span class="line"><span>$ git worktree add ~/trees/oalders/feature-Y -b oalders/feature-Y e9df3c555e96b3f1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/Users/olaf/http-browserdetect       90772ae [master]</span></span>
<span class="line"><span>/Users/olaf/trees/oalders/feature-X  90772ae [oalders/feature-X]</span></span>
<span class="line"><span>/Users/olaf/trees/oalders/feature-Y  e9df3c5 [oalders/feature-Y]</span></span></code></pre></div><p>與大多數其他 Git 命令一樣，你需要在倉庫路徑下使用此命令。一旦創建了工作樹，就有了隔離的工作環境。Git 倉庫會跟蹤工作樹在磁盤上的位置。如果 Git 鈎子已經在父倉庫中設置好了，那麼它們也可以在工作樹中使用。</p><p>請注意到，每個工作樹只使用父倉庫磁盤空間的一小部分。在這種情況下，工作樹需要只大約三分之一的原始磁盤空間。這這非常適合進行擴展。如果你的倉庫達到了千兆字節的級別，你就會真正體會到工作樹對硬盤空間的節省。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du -sh /Users/olaf/http-browserdetect</span></span>
<span class="line"><span>2.9M</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ du -sh /Users/olaf/trees/oalders/feature-X</span></span>
<span class="line"><span>1.0M</span></span></code></pre></div><p><strong>優點：</strong> 你可以同時在多個工作區中工作。你不需要使用暫存。Git 會跟蹤所有的工作樹。你不需要設置 Git 鈎子。這也比 <code>git clone</code> 更快，並且可以節省網絡流量，因為你可以在飛行模式下執行此操作。你還可以更高效地使用磁盤空間，而無需藉助於淺層克隆。</p><p><strong>缺點：</strong> 這是個需要你額外學習和記憶的新東西，但是如果你能養成使用這個功能的習慣，它會給你豐厚的回報。</p><h4 id="額外的小技巧" tabindex="-1">額外的小技巧 <a class="header-anchor" href="#額外的小技巧" aria-label="Permalink to “額外的小技巧”">​</a></h4><p>有很多方式可以清除工作樹，最受歡迎的方式是使用 Git 來移除工作樹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git worktree remove /Users/olaf/trees/oalders/feature-X</span></span></code></pre></div><p>如果你喜歡 RM 大法，你也可以用 <code>rm -rf</code> 來刪除工作樹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -rf /Users/olaf/trees/oalders/feature-X</span></span></code></pre></div><p>但是，如果執行此操作，則可能需要使用 <code>git worktree prune</code> 清理所有剩餘的文件。或者你現在可以跳過清理，這將在將來的某個時候通過 <code>git gc</code> 自行完成。</p><h4 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to “注意事項”">​</a></h4><p>如果你準備嘗試 <code>git worktree</code>，請記住以下幾點：</p><ul><li>刪除工作樹並不會刪除該分支。</li><li>可以在工作樹中切換分支。</li><li>你不能在多個工作樹中同時簽出同一個分支。</li><li>像其他命令一樣，<code>git worktree</code> 需要從倉庫內運行。</li><li>你可以同時擁有許多工作樹。</li><li>要從同一個本地倉庫簽出創建工作樹，否則它們將互不可知。</li></ul><h4 id="git-rev-parse" tabindex="-1">git rev-parse <a class="header-anchor" href="#git-rev-parse" aria-label="Permalink to “git rev-parse”">​</a></h4><p>最後一點注意：在使用 <code>git worktree</code> 時，倉庫根所在的位置可能取決於上下文。幸運的是，<code>git rev parse</code> 可以讓你區分這兩者。</p><ul><li>要查找父倉庫的根目錄，請執行以下操作：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git rev-parse --git-common-dir</span></span></code></pre></div></li><li>要查找你當前所在倉庫的根目錄，請執行：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git rev-parse --show-toplevel</span></span></code></pre></div></li></ul><h3 id="根據你的需要選擇最好的方法" tabindex="-1">根據你的需要選擇最好的方法 <a class="header-anchor" href="#根據你的需要選擇最好的方法" aria-label="Permalink to “根據你的需要選擇最好的方法”">​</a></h3><p>就像很多事情一樣，TIMTOWDI（<ruby>條條大道通羅馬<rt>there&#39;s more than one way to do it</rt></ruby>）。重要的是你要找到一個適合你需要的工作流程。你的需求可能因手頭的問題而異。也許你偶爾會發現自己將 <code>git worktree</code> 作為版本控制工具箱中的一個方便工具。</p><hr>`,51)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),a(t,{href:"https://opensource.com/article/21/4/context-switching-git"},{default:i(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/21/4/context-switching-git",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),a(t,{href:"https://opensource.com/users/oalders"},{default:i(()=>[...e[2]||(e[2]=[s("Olaf Alders",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(t,{href:"https://github.com/Chao-zhi"},{default:i(()=>[...e[4]||(e[4]=[s("Chao-zhi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const C=l(c,[["render",h]]);export{w as __pageData,C as default};
